from __future__ import annotations


REVIEW_WORKSTATION_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Vidrensic Review Workstation</title>
<style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0b0f14;color:#e6edf3}*{box-sizing:border-box}body{margin:0}.shell{display:grid;grid-template-columns:330px 1fr;min-height:100vh}.side{padding:12px;border-right:1px solid #27303a;background:#0e131a;overflow:auto}.main{padding:12px;min-width:0}.row{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.grow{margin-right:auto}button,input,textarea,select{font:inherit}button,input,textarea,select{background:#111821;color:#e6edf3;border:1px solid #303844;border-radius:7px;padding:7px}button{cursor:pointer}button.active{border-color:#6ea8fe}button.keep{border-color:#3fb950}button.discard{border-color:#f85149}input,textarea,select{width:100%}.filters{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin:8px 0}.filters2{display:grid;grid-template-columns:1fr 1fr;gap:5px}.small{font-size:11px;color:#8b949e}.list{display:flex;flex-direction:column;gap:6px;margin-top:8px}.itemrow{display:grid;grid-template-columns:22px 1fr;gap:4px}.item{width:100%;text-align:left;background:#111821;border:1px solid #242b34;border-radius:7px;padding:8px}.item.selected{border-color:#6ea8fe}.item.changed{border-color:#f85149}.title{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.meta{font-size:10px;color:#8b949e;display:flex;gap:6px;flex-wrap:wrap;margin-top:4px}.state{font-weight:700}.KEEP{color:#3fb950}.REVIEW{color:#d29922}.DISCARD{color:#f85149}.panel{border:1px solid #242b34;border-radius:9px;background:#0e131a;padding:10px;margin-bottom:10px}.player{position:sticky;top:12px;z-index:3}.player video{width:100%;max-height:46vh;background:#000;border-radius:6px;display:block}.controls{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.timeline{position:relative;height:26px;border:1px solid #303844;border-radius:6px;background:#10161e;margin-top:8px;cursor:pointer}.fill{position:absolute;inset:0 auto 0 0;width:0;background:#26364d}.mark{position:absolute;top:0;bottom:0;width:2px;background:#d29922}.mark.book{width:3px;background:#58a6ff}.detail{display:grid;grid-template-columns:1fr 1fr;gap:10px}.matrix{display:grid;grid-template-columns:1fr 1fr;gap:8px}.slot{border:1px solid #242b34;border-radius:7px;overflow:hidden;background:#080c11}.slot header{padding:6px 7px;font-size:11px;color:#aab4c0;display:flex;justify-content:space-between}.slot video{width:100%;display:block;max-height:250px;background:#000}.contact{display:grid;grid-template-columns:repeat(6,1fr);gap:5px}.thumb{aspect-ratio:16/9;padding:0;position:relative;overflow:hidden;background:#000}.thumb canvas{width:100%;height:100%}.thumb span{position:absolute;left:3px;bottom:3px;font-size:9px;background:#000c;padding:2px 4px;border-radius:3px}.banner{display:none;margin-top:7px;padding:7px;border:1px solid #7d2d2d;border-radius:6px;background:#2a1518;color:#ffb4ad;font-size:11px}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid #27303a}.detail,.matrix{grid-template-columns:1fr}.contact{grid-template-columns:repeat(3,1fr)}}
</style></head><body>
<div class="shell"><aside class="side">
<div class="row"><strong class="grow">Vidrensic Review</strong><span id="count" class="small">0</span></div>
<input id="search" placeholder="Search artifact / kind / note"><div class="filters">
<button data-filter="ALL" class="filter active">All</button><button data-filter="REVIEW" class="filter">Review</button><button data-filter="KEEP" class="filter">Keep</button></div>
<div class="filters"><button data-filter="DISCARD" class="filter">Discard</button><button id="refresh">Refresh</button><button id="clear">Clear</button></div>
<div class="filters2"><input id="date" type="date" title="Review update date UTC"><select id="hour" title="Review update hour UTC"><option value="">Any hour</option><option>00</option><option>01</option><option>02</option><option>03</option><option>04</option><option>05</option><option>06</option><option>07</option><option>08</option><option>09</option><option>10</option><option>11</option><option>12</option><option>13</option><option>14</option><option>15</option><option>16</option><option>17</option><option>18</option><option>19</option><option>20</option><option>21</option><option>22</option><option>23</option></select></div>
<div class="small" style="margin-top:6px">Date/hour filters use review-update UTC; recorder wall-clock metadata is not currently part of ReviewItem.</div>
<div class="row" style="margin-top:7px"><button id="matrix-open">Open matrix</button><button id="matrix-clear">Clear matrix</button></div>
<div id="items" class="list"></div></aside>
<main class="main"><div class="panel"><div class="row"><strong id="name" class="grow">Select a review item</strong><span id="state" class="state REVIEW">REVIEW</span><span id="hash" class="small">SHA-256: —</span></div><div id="status" class="small" style="margin-top:5px"></div><div id="banner" class="banner"></div></div>
<section class="panel player"><video id="player" controls preload="metadata"></video><div class="row" style="margin-top:6px"><span id="clock" class="small grow">00:00 / —</span><span id="qc" class="small"></span></div>
<div class="controls"><button data-j="-30">−30</button><button data-j="-5">−5</button><button data-j="-1">−1</button><button id="back">Frame −</button><button id="forward">Frame +</button><button data-j="1">+1</button><button data-j="5">+5</button><button data-j="30">+30</button><button data-s=".25">.25×</button><button data-s=".5">.5×</button><button data-s="1" class="active">1×</button><button data-s="2">2×</button><button data-s="5">5×</button><button data-s="8">8×</button><button id="retry">Reload</button></div>
<div id="track" class="timeline"><div id="fill" class="fill"></div><div id="markers"></div></div><div class="small">orange = timing anomaly · blue = bookmark</div></section>
<section id="matrix" class="panel matrix" style="display:none"></section>
<section class="panel"><div class="row"><strong class="grow">Visual triage contact sheet</strong><span class="small">in-browser triage aid; not exact frame evidence</span></div><div id="contact" class="contact" style="margin-top:7px"></div></section>
<section class="detail"><div class="panel"><strong>Review decision</strong><div class="controls"><button id="keep" class="keep">KEEP</button><button id="review">REVIEW</button><button id="discard" class="discard">DISCARD</button></div><textarea id="note" placeholder="Analyst note" style="margin-top:7px"></textarea><button id="save" style="margin-top:6px">Save note</button></div>
<div class="panel"><strong>Bookmarks</strong><div class="row" style="margin-top:7px"><input id="label" placeholder="Label" class="grow"><button id="bookmark">Bookmark current</button></div><div id="bookmarks" style="margin-top:6px"></div></div></section>
</main></div>
<script>
const S={items:[],filter:'ALL',selected:null,detail:null,timeline:null,matrix:[],retry:0};const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const t=v=>{if(!Number.isFinite(v))return'—';v=Math.max(0,Math.round(v));const h=Math.floor(v/3600),m=Math.floor(v%3600/60),s=v%60;return h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`};
function msg(v){$('status').textContent=v||''}async function api(p,o={}){const r=await fetch(p,o);const d=await r.json().catch(()=>({error:'invalid response'}));if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d}function matches(i){const q=$('search').value.trim().toLowerCase();if(q&&!`${i.artifact} ${i.kind} ${i.note}`.toLowerCase().includes(q))return false;const u=i.updated_utc||'';if($('date').value&&!u.startsWith($('date').value))return false;if($('hour').value&&!u.includes(`T${$('hour').value}:`))return false;return true}
async function load(){const q=S.filter==='ALL'?'':`?state=${S.filter}`;S.items=(await api('/api/items'+q)).items||[];renderList();$('count').textContent=S.items.length;if(S.selected)await open(S.selected)}
function renderList(){const list=S.items.filter(matches);$('items').innerHTML=list.length?list.map(i=>`<div class="itemrow"><label><input type="checkbox" data-m="${esc(i.item_id)}" ${S.matrix.includes(i.item_id)?'checked':''}></label><button class="item ${i.item_id===S.selected?'selected':''} ${i.artifact_changed?'changed':''}" data-i="${esc(i.item_id)}"><div class="title">${esc(i.artifact.split('/').pop())}</div><div class="meta"><span class="state ${i.state}">${i.state}</span><span>${t(i.duration_seconds)}</span><span>${esc(i.kind)}</span><span>${i.bookmark_count||0} marks</span><span>${esc(i.updated_utc||'')}</span></div></button></div>`).join(''):'<div class="small">No matching review items</div>';document.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>open(b.dataset.i));document.querySelectorAll('[data-m]').forEach(b=>b.onchange=()=>toggleMatrix(b.dataset.m,b.checked))}
async function open(id){S.selected=id;S.retry=0;renderList();try{const d=await api('/api/item/'+encodeURIComponent(id));S.detail=d;$('name').textContent=d.artifact.split('/').pop();$('hash').textContent='SHA-256: '+d.artifact_sha256.slice(0,16)+'…';$('state').textContent=d.state;$('state').className='state '+d.state;$('note').value=d.note||'';$('player').src='/media/'+encodeURIComponent(id);$('player').load();renderBookmarks(d.bookmarks||[]);await timeline(id);await contact(d);msg(d.artifact_changed?'WARNING: artifact identity changed after registration.':'Ready')}catch(e){msg(e.message)}}
async function timeline(id){S.timeline=null;$('qc').textContent='';marks();try{const d=await api('/api/timeline/'+encodeURIComponent(id));S.timeline=d;const x=d.timeline||{};$('qc').textContent=`Duration ${x.duration_confidence||'—'} · FPS ${x.frame_rate_confidence||'—'} · ${x.truncated?'TRUNCATED':'complete'}`;marks()}catch(e){if(!e.message.includes('no timeline report'))msg('Timeline: '+e.message)}}
function renderBookmarks(bs){$('bookmarks').innerHTML=bs.length?bs.map(b=>`<div class="row" style="padding:4px 0;border-bottom:1px solid #1e252e"><span>${t(b.timestamp_seconds)}</span><span>${esc(b.label||'Bookmark')}</span><span class="small grow">${esc(b.note||'')}</span><button data-g="${b.timestamp_seconds}">Go</button></div>`).join(''):'<div class="small">No bookmarks</div>';document.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>seek(Number(b.dataset.g)));marks()}
function marks(){const box=$('markers');box.innerHTML='';const d=Number($('player').duration)||Number(S.detail?.duration_seconds)||0;if(!d)return;for(const b of(S.detail?.bookmarks||[])){const e=document.createElement('div');e.className='mark book';e.style.left=`${Math.min(100,b.timestamp_seconds/d*100)}%`;box.appendChild(e)}for(const a of(S.timeline?.timeline?.anomalies||[])){const x=Number(a.current??a.previous??0),e=document.createElement('div');e.className='mark';e.style.left=`${Math.min(100,Math.max(0,x/d*100))}%`;box.appendChild(e)}}
function seek(v){const p=$('player'),d=Number(p.duration)||Number(S.detail?.duration_seconds)||0;if(d)p.currentTime=Math.max(0,Math.min(d,v))}function update(){const p=$('player'),d=Number.isFinite(p.duration)?p.duration:Number(S.detail?.duration_seconds)||NaN;$('clock').textContent=`${t(p.currentTime)} / ${t(d)}`;$('fill').style.width=d>0?`${p.currentTime/d*100}%`:'0%';sync()}function sync(){const p=$('player');document.querySelectorAll('[data-v]').forEach(v=>{if(v===p)return;const d=Math.abs((Number(v.currentTime)||0)-(Number(p.currentTime)||0));if(d>.12)try{v.currentTime=p.currentTime}catch{}})}
async function recover(reason){if(!S.detail)return;if(S.retry>=2){$('banner').style.display='block';$('banner').textContent='Playback recovery exhausted; inspect media/QC or use manual reload.';return}S.retry++;const pos=Number($('player').currentTime)||0;$('banner').style.display='block';$('banner').textContent=`Playback interruption (${reason}); restoring ${t(pos)}…`;const p=$('player');p.src='/media/'+encodeURIComponent(S.detail.item_id)+'?retry='+Date.now();p.load();p.addEventListener('loadedmetadata',()=>{seek(pos);$('banner').style.display='none';msg(`Recovered at ${t(pos)}`)},{once:true})}
async function contact(d){const c=$('contact');c.innerHTML='';const dur=Number(d.duration_seconds)||0;if(d.artifact_changed||dur<=0){c.innerHTML='<div class="small">Contact sheet unavailable for unstable/no-duration media.</div>';return}const v=$('player'),old=Number(v.currentTime)||0,was=v.paused;for(let i=0;i<12;i++){const b=document.createElement('button');b.className='thumb';const ca=document.createElement('canvas');ca.width=320;ca.height=180;b.appendChild(ca);const sp=document.createElement('span');const when=dur*i/11;sp.textContent=t(when);b.appendChild(sp);b.onclick=()=>seek(when);c.appendChild(b);await new Promise(done=>{const on=()=>{try{ca.getContext('2d').drawImage(v,0,0,ca.width,ca.height)}catch{}v.removeEventListener('seeked',on);done()};v.addEventListener('seeked',on,{once:true});seek(when);setTimeout(done,1200)})}seek(old);if(!was)v.play().catch(()=>{});}
function toggleMatrix(id,on){if(on){if(S.matrix.length>=4){msg('Maximum 4 candidates in synchronized matrix.');renderList();return}if(!S.matrix.includes(id))S.matrix.push(id)}else S.matrix=S.matrix.filter(x=>x!==id);renderList()}
function matrix(){const box=$('matrix');if(!S.matrix.length){box.style.display='none';box.innerHTML='';return}box.style.display='grid';box.innerHTML=S.matrix.map((id,n)=>{const i=S.items.find(x=>x.item_id===id)||{};return `<div class="slot"><header><span>Candidate ${n+1}</span><span>${esc((i.artifact||'').split('/').pop())}</span></header><video controls preload="metadata" data-v="${esc(id)}" src="/media/${encodeURIComponent(id)}"></video></div>`}).join('');document.querySelectorAll('[data-v]').forEach(v=>v.addEventListener('play',()=>{document.querySelectorAll('[data-v]').forEach(x=>{if(x!==v)x.currentTime=v.currentTime})}));}
async function mutate(path,body){return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}async function setState(x){if(!S.detail)return;S.detail={...S.detail,...await mutate(`/api/item/${S.detail.item_id}/state`,{state:x,sha256:S.detail.artifact_sha256})};$('state').textContent=x;$('state').className='state '+x;await load();msg('State updated: '+x)}
$('player').onloadedmetadata=()=>{marks();update()};$('player').ontimeupdate=update;$('player').onstalled=()=>recover('stalled');$('player').onerror=()=>recover('media error');$('player').onwaiting=()=>msg('Buffering…');document.querySelectorAll('[data-j]').forEach(b=>b.onclick=()=>seek(($('player').currentTime||0)+Number(b.dataset.j)));document.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{$('player').playbackRate=Number(b.dataset.s);document.querySelectorAll('[data-s]').forEach(x=>x.classList.toggle('active',x===b))});$('back').onclick=()=>seek(($('player').currentTime||0)-1/30);$('forward').onclick=()=>seek(($('player').currentTime||0)+1/30);$('track').onclick=e=>{const r=$('track').getBoundingClientRect(),d=Number($('player').duration)||Number(S.detail?.duration_seconds)||0;seek((e.clientX-r.left)/r.width*d)};$('retry').onclick=()=>{S.retry=0;recover('manual reload')};$('keep').onclick=()=>setState('KEEP');$('review').onclick=()=>setState('REVIEW');$('discard').onclick=()=>setState('DISCARD');$('save').onclick=async()=>{S.detail={...S.detail,...await mutate(`/api/item/${S.detail.item_id}/note`,{note:$('note').value,sha256:S.detail.artifact_sha256})};await load();msg('Note saved')};$('bookmark').onclick=async()=>{const b=await mutate(`/api/item/${S.detail.item_id}/bookmark`,{timestamp_seconds:$('player').currentTime||0,label:$('label').value,note:$('note').value.slice(0,512),sha256:S.detail.artifact_sha256});S.detail.bookmarks=[...(S.detail.bookmarks||[]),b].sort((a,b)=>a.timestamp_seconds-b.timestamp_seconds);$('label').value='';renderBookmarks(S.detail.bookmarks);msg('Bookmark created')};document.querySelectorAll('.filter').forEach(b=>b.onclick=async()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));S.filter=b.dataset.filter;await load()});$('search').oninput=renderList;$('date').oninput=renderList;$('hour').onchange=renderList;$('refresh').onclick=load;$('clear').onclick=()=>{$('search').value='';$('date').value='';$('hour').value='';renderList()};$('matrix-open').onclick=()=>{matrix();if(S.matrix.length)$('matrix').scrollIntoView({behavior:'smooth'})};$('matrix-clear').onclick=()=>{S.matrix=[];renderList();matrix()};load().catch(e=>msg(e.message));
</script></body></html>
'''
